"use client";

import { useEffect } from "react";

const CHAT_ID = "b1dxhqo21i";
const WIDGET_SRC = "https://d36ewmyb2wrx29.cloudfront.net/index.js";

export default function SkillyWidget() {
  useEffect(() => {
    window.chatConfig = { chatId: CHAT_ID, env: "skl" };

    let attempt = 0;
    let timer;

    const load = () => {
      document.querySelector("script[data-skilly]")?.remove();
      const script = document.createElement("script");
      script.src = WIDGET_SRC;
      script.async = true;
      script.dataset.skilly = "true";
      script.onerror = () => {
        if (attempt++ < 3) timer = setTimeout(load, 1000 * attempt);
      };
      document.body.appendChild(script);
    };

    if (!document.querySelector("script[data-skilly]")) load();
    return () => clearTimeout(timer);
  }, []);

  return null;
}
